\overline{\overline{I}}
= I_{ik} = 
\begin{pmatrix}
I_{xx} & I_{xy} & I_{xz} \\
I_{yx} & I_{yy} & I_{yz} \\
I_{zx} & I_{zy} & I_{zz} \\
\end{pmatrix}
=
\begin{pmatrix}
\iiint \tilde{\rho}(\vec{r}) (y^2 + z^2) dV  &  - \iiint \tilde{\rho}(\vec{r}) x y dV  &  - \iiint \tilde{\rho}(\vec{r}) x z dV \\
- \iiint \tilde{\rho}(\vec{r}) y x dV  &  \iiint \tilde{\rho}(\vec{r}) (x^2 + z^2) dV  &  - \iiint \tilde{\rho}(\vec{r}) y z dV \\
